import gurobipy as gp
from gurobipy import GRB
school_caps = {}
neigh_pops = {}
distances = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('school_capacity.csv'):
        school = vals['School']
        cap = int(vals['Capacity'])
        school_caps[school] = cap
    elif src.endswith('neighborhoods_population.csv'):
        n = vals['Neighborhood']
        w = int(vals['Population_White'])
        nw = int(vals['Population_NonWhite'])
        neigh_pops[n] = {'W': w, 'NW': nw}
    elif src.endswith('distance.csv'):
        school = vals['School']
        distances[school] = {}
        for n, d in vals.items():
            if n == 'School':
                continue
            distances[school][n] = float(d)
schools = sorted(school_caps)
neighs = sorted(neigh_pops)
races = ['W', 'NW']
for s in schools:
    for n in neighs:
        if n not in distances[s]:
            raise ValueError(f'Missing distance for school {s}, neighborhood {n}')
for n in neighs:
    for r in races:
        if r not in neigh_pops[n]:
            raise ValueError(f'Missing population for neighborhood {n}, race {r}')
P_total_W = sum((neigh_pops[n]['W'] for n in neighs))
P_total_NW = sum((neigh_pops[n]['NW'] for n in neighs))
P_total = P_total_W + P_total_NW
r_district = P_total_W / P_total if P_total > 0 else 0.0
delta = 0.1
r_lb = r_district - delta
r_ub = r_district + delta
m = gp.Model('school_assignment')
x_vars = m.addVars(schools, neighs, races, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((distances[s][n] * x_vars[s, n, r] for s in schools for n in neighs for r in races)), GRB.MINIMIZE)
for n in neighs:
    for r in races:
        m.addConstr(gp.quicksum((x_vars[s, n, r] for s in schools)) == neigh_pops[n][r], name='')
for s in schools:
    m.addConstr(gp.quicksum((x_vars[s, n, r] for n in neighs for r in races)) <= school_caps[s], name='')
for s in schools:
    white = gp.quicksum((x_vars[s, n, 'W'] for n in neighs))
    total = gp.quicksum((x_vars[s, n, r] for n in neighs for r in races))
    m.addConstr(white >= r_lb * total, name='')
    m.addConstr(white <= r_ub * total, name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')